import random, sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/vendor')
import controller

def cost_scale_dbg(nodes, arcs, flow):
    m = len(arcs); scale = nodes + 1
    tail=[];to=[];cost=[];cap=[];adj=[[] for _ in range(nodes)]
    for i,(u,v,low,high,c) in enumerate(arcs):
        tail.append(u);to.append(v);cost.append(c*scale);cap.append(high-flow[i]);adj[u].append(2*i)
        tail.append(v);to.append(u);cost.append(-c*scale);cap.append(flow[i]-low);adj[v].append(2*i+1)
    pot=[0]*nodes; excess=[0]*nodes
    peak=max(abs(c) for c in cost); eps=max(1,peak//nodes)
    rnd=0
    while True:
        for edge in range(len(to)):
            if cap[edge]>0:
                u=tail[edge];v=to[edge]
                if cost[edge]+pot[u]-pot[v]<0:
                    amt=cap[edge];cap[edge]=0;cap[edge^1]+=amt
                    excess[u]-=amt;excess[v]+=amt
        # invariant check after phase 1
        bad=0
        for edge in range(len(to)):
            if cap[edge]>0:
                u=tail[edge];v=to[edge]
                if cost[edge]+pot[u]-pot[v] < 0: bad+=1
        print('round',rnd,'eps',eps,'phase1 residual arcs with rc<0:',bad)
        active=[n for n in range(nodes) if excess[n]>0]; queued=set(active)
        while active:
            u=active.pop();queued.discard(u)
            while excess[u]>0:
                pushed=False
                for edge in adj[u]:
                    if cap[edge]>0:
                        v=to[edge]
                        if cost[edge]+pot[u]-pot[v]<0:
                            amt=cap[edge]
                            if excess[u]<amt: amt=excess[u]
                            cap[edge]-=amt;cap[edge^1]+=amt
                            excess[u]-=amt;excess[v]+=amt
                            if excess[v]>0 and v not in queued:
                                queued.add(v);active.append(v)
                            pushed=True;break
                if not pushed:
                    best=None
                    for edge in adj[u]:
                        if cap[edge]>0:
                            val=pot[to[edge]]-cost[edge]
                            if best is None or val<best: best=val
                    if best is None:
                        print('  STUCK node',u,'excess',excess[u]); excess[u]=0;break
                    pot[u]=best-eps
        # invariant after refine
        worst=0
        for edge in range(len(to)):
            if cap[edge]>0:
                u=tail[edge];v=to[edge]
                worst=min(worst, cost[edge]+pot[u]-pot[v])
        print('  after refine: worst rc =',worst,'(should be >= -eps =',-eps,')  excess sum',sum(excess))
        if eps==1: break
        eps=max(1,eps//4); rnd+=1
    out=[arcs[i][3]-cap[2*i] for i in range(m)]
    return out

def feasible_flow(nodes, arcs):
    bal=[0]*nodes
    for (u,v,lo,hi,c) in arcs: bal[u]-=lo; bal[v]+=lo
    net2=controller._FlowNetwork(nodes+2)
    for (u,v,lo,hi,c) in arcs: net2.add(u,v,hi-lo)
    ss,tt=nodes,nodes+1
    for v in range(nodes):
        if bal[v]>0: net2.add(ss,v,bal[v])
        elif bal[v]<0: net2.add(v,tt,-bal[v])
    val=net2.max_flow(ss,tt,sum(x for x in bal if x>0))
    if val<sum(x for x in bal if x>0): return None
    return [lo+net2.cap[2*i^1] for i,(u,v,lo,hi,c) in enumerate(arcs)]

rng=random.Random(999)
for trial in range(3):
    n=rng.randint(3,14); arcs=[]
    for i in range(2*n):
        u=rng.randrange(n);v=rng.randrange(n)
        if u==v: v=(v+1)%n
        low=rng.choice([0,0,0,1]);high=low+rng.choice([0,1,2,5]);cost=rng.choice([-10,-3,-1,0,1,4,7])
        arcs.append((u,v,low,high,cost))
    flow=feasible_flow(n,arcs)
    if trial==2:
        f2=cost_scale_dbg(n,arcs,list(flow))
        print('flow',f2,'cost',sum(c*f2[i] for i,(u,v,lo,hi,c) in enumerate(arcs)))
